import{_ as r,c as s,o as a,ah as t,j as e,a as i}from"./chunks/framework.NihXuq1j.js";const d="/Qonnectra-docs/pr-20/images/manual/teil-a/error_toast.jpg",h="/Qonnectra-docs/pr-20/images/manual/teil-a/error_not_found.jpg",l="/Qonnectra-docs/pr-20/images/manual/teil-a/error_permission.jpg",o="/Qonnectra-docs/pr-20/videos/error_permission.webm",u="/Qonnectra-docs/pr-20/images/manual/teil-a/error_map_empty.jpg",c="/Qonnectra-docs/pr-20/images/manual/teil-a/error_support_info.jpg",A=JSON.parse('{"title":"18. Wenn etwas nicht funktioniert","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/18-wenn-etwas-nicht-funktioniert.md","filePath":"manual/teil-a-anwenderhandbuch/18-wenn-etwas-nicht-funktioniert.md"}'),g={name:"manual/teil-a-anwenderhandbuch/18-wenn-etwas-nicht-funktioniert.md"};function m(b,n,p,f,w,k){return a(),s("div",null,[...n[0]||(n[0]=[t('<h1 id="_18-wenn-etwas-nicht-funktioniert" tabindex="-1">18. Wenn etwas nicht funktioniert <a class="header-anchor" href="#_18-wenn-etwas-nicht-funktioniert" aria-label="Permalink to &quot;18. Wenn etwas nicht funktioniert&quot;">​</a></h1><p>Dieses Kapitel sammelt die Fälle, die in jeder Ansicht auftreten können: die Meldungen, mit denen Qonnectra antwortet, eine abgelaufene Anmeldung, fehlende Rechte und leere Karten und Diagramme. Am Ende steht, was das Support-Team von Ihnen braucht, damit es Ihnen helfen kann.</p><p>Was nur in einer bestimmten Ansicht schiefgehen kann, steht in deren Kapitel – etwa eine fehlgeschlagene Route in der <a href="./11-rohrzuordnung.html">Rohrzuordnung</a> oder ein Import mit Fehlern in der <a href="./10-rohrverwaltung.html">Rohrverwaltung</a>.</p><h2 id="_18-1-meldungen-der-anwendung-und-was-sie-bedeuten" tabindex="-1">18.1 Meldungen der Anwendung und was sie bedeuten <a class="header-anchor" href="#_18-1-meldungen-der-anwendung-und-was-sie-bedeuten" aria-label="Permalink to &quot;18.1 Meldungen der Anwendung und was sie bedeuten&quot;">​</a></h2><p>Qonnectra antwortet auf jede Aktion, die etwas an den Daten ändert, mit einer kurzen Meldung am unteren Bildschirmrand. Sie besteht aus einer Überschrift – „Erfolg“ oder „Fehler“ – und einem Satz dazu, etwa „Adresse erfolgreich aktualisiert“ oder „Fehler beim Löschen des Rohres“.</p><p><img src="'+d+'" alt="Screenshot einer Adresse mit Hervorhebung der Meldung „Adresse erfolgreich aktualisiert“ am unteren Bildschirmrand" data-zoomable="true"></p><p>Die beiden Überschriften sind verlässlich:</p><ul><li><strong>„Erfolg“</strong> heißt, dass der Server die Änderung angenommen und gespeichert hat. Sie können weiterarbeiten.</li><li><strong>„Fehler“</strong> heißt, dass nichts geändert wurde. Ihre Eingaben stehen weiter im Formular und lassen sich erneut absenden.</li></ul><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Meldung verschwindet nach wenigen Sekunden von selbst. Wer währenddessen woanders hinsieht, bekommt nicht mit, ob gespeichert wurde – und ein Formular sieht danach genauso aus wie vorher. Prüfen Sie im Zweifel nach, ob der Wert wirklich in der Ansicht steht, und laden Sie die Seite dafür neu.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Bei Abläufen aus mehreren Schritten gilt „Fehler“ nur für den Schritt, in dem er auftritt. In der Nachverdichtung etwa wird der geänderte Ausbaustatus gespeichert, auch wenn das PDF danach nicht zustande kommt, siehe Abschnitt <a href="./07-nachverdichtung.html#_7-4-pdf-erzeugen-und-inhalt-des-dokuments">PDF erzeugen und Inhalt des Dokuments</a>.</p></div><p><strong>Rückfragen</strong></p><p>Vor dem Löschen und vor dem Neuvergeben einer ID fragt Qonnectra in einem kleinen Fenster nach. Es nennt, was passieren wird, und bietet „Abbrechen“ und die Aktion selbst an. „Abbrechen“ oder ein Klick daneben lässt alles, wie es war.</p><p><strong>Hinweise anstelle von Inhalten</strong></p><p>Steht in einer Tabelle oder einem Abschnitt ein Satz wie „Keine Ergebnisse gefunden“, „Keine Daten verfügbar“ oder „Keine Standortdaten verfügbar“, ist das keine Fehlermeldung: An dieser Stelle gibt es nichts anzuzeigen. Das kann an einem Filter liegen, an einem leeren Projekt oder an fehlenden Stammdaten, siehe Abschnitt <a href="#_18-4-karte-oder-diagramm-bleibt-leer">Karte oder Diagramm bleibt leer</a>.</p><p><strong>Die Wartemeldung</strong></p><p>Beim Wechsel in eine andere Ansicht legt sich kurz ein Fenster mit „Laden...“ und „Bitte warten...“ über die Oberfläche; beim Netzschema steht dort „Netzwerkschema synchronisiert...“. Bleibt es stehen, statt nach ein paar Sekunden zu verschwinden, kommt die Ansicht nicht zustande. Laden Sie die Seite neu; bleibt es dabei, siehe Abschnitt <a href="#_18-5-was-das-support-team-von-ihnen-braucht">Was das Support-Team von Ihnen braucht</a>.</p><p><strong>Die Fehlerseite</strong></p><p>Führt eine Adresse ins Leere, ersetzt Qonnectra die Ansicht durch eine Seite mit einer Zahl – dem HTTP-Statuscode – und darunter einem kurzen englischen Text, etwa der 404 mit „Not Found“. „Zurück zur Startseite“ bringt Sie in die Anwendung zurück.</p><p><img src="'+h+'" alt="Screenshot der Fehlerseite mit der Statusnummer 404, dem Text „Not Found“ und der Schaltfläche „Zurück zur Startseite“" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Ein tippfehlerhaft eingegebener Link ist die häufigste Ursache. Kommt die Seite bei einem Verweis aus Qonnectra selbst oder aus diesem Handbuch, notieren Sie die Zahl und die Adresse und melden Sie es, siehe Abschnitt <a href="#_18-5-was-das-support-team-von-ihnen-braucht">Was das Support-Team von Ihnen braucht</a>.</p></div><h2 id="_18-2-sitzung-abgelaufen-anmeldung-schlagt-fehl" tabindex="-1">18.2 Sitzung abgelaufen, Anmeldung schlägt fehl <a class="header-anchor" href="#_18-2-sitzung-abgelaufen-anmeldung-schlagt-fehl" aria-label="Permalink to &quot;18.2 Sitzung abgelaufen, Anmeldung schlägt fehl&quot;">​</a></h2><p><strong>Die Anmeldung schlägt fehl</strong></p><p>Stimmen Benutzername oder Passwort nicht, bleiben Sie auf der Anmeldeseite und Qonnectra meldet „Fehler beim Anmelden“, siehe Abschnitt <a href="./01-erste-schritte.html#_1-1-anmelden-und-abmelden">Anmelden und abmelden</a>. Welches der beiden Felder falsch war, nennt die Meldung nicht. Prüfen Sie die Groß- und Kleinschreibung und ob die Feststelltaste eingeschaltet ist. Nach mehreren Versuchen hilft nur Ihre Administration weiter, siehe Abschnitt <a href="./01-erste-schritte.html#_1-1-2-passwort-vergessen">Passwort vergessen?</a>.</p><p><strong>Die Sitzung ist abgelaufen</strong></p><p>Ihre Anmeldung verlängert sich, solange Sie mit Qonnectra arbeiten. Liegt die Anwendung dagegen länger als eine Woche ungenutzt, ist sie abgelaufen: Der nächste Klick bringt Sie auf die Anmeldeseite. Melden Sie sich dort erneut an.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Nach der erneuten Anmeldung landen Sie auf dem Dashboard, nicht auf der Seite, auf der Sie vorher waren. Notieren Sie sich vorher, wo Sie gearbeitet haben.</p></div><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Läuft die Sitzung ab, während ein Formular offen steht, scheitert „Speichern“ mit der gewöhnlichen Fehlermeldung, und beim erneuten Anmelden gehen die Eingaben verloren. Kopieren Sie längere Texte vorher heraus.</p></div><p><strong>Abmelden wirkt überall</strong></p><p>Die Anmeldung gilt für den ganzen Browser. Melden Sie sich in einem Reiter ab, sind auch die übrigen Reiter abgemeldet; der nächste Klick darin führt auf die Anmeldeseite.</p><h2 id="_18-3-fehlende-rechte-erkennen" tabindex="-1">18.3 Fehlende Rechte erkennen <a class="header-anchor" href="#_18-3-fehlende-rechte-erkennen" aria-label="Permalink to &quot;18.3 Fehlende Rechte erkennen&quot;">​</a></h2><p>Was Sie sehen und ändern dürfen, hängt an der Rolle Ihres Kontos, siehe Abschnitt <a href="./01-erste-schritte.html#_1-7-warum-manche-menupunkte-fehlen-berechtigungen">Warum manche Menüpunkte fehlen: Berechtigungen</a>. Fehlende Rechte zeigen sich auf drei Arten, und nur eine davon sagt es Ihnen auch:</p><ol><li><strong>Der Menüpunkt fehlt.</strong> Ein Bereich, den dieses Handbuch beschreibt, steht nicht in der Navigationsleiste.</li><li><strong>Die Anwendung springt weg.</strong> Rufen Sie eine gesperrte Adresse direkt auf – über ein Lesezeichen oder einen Link –, landen Sie ohne jede Meldung in der Karte. Das sieht aus, als hätte der Link nicht funktioniert.</li><li><strong>Die Aktion scheitert.</strong> Der Button ist da, die Rückfrage kommt, und danach erscheint die Meldung „Sie sind nicht berechtigt, diese Aktion durchzuführen.“ Die Daten bleiben unverändert.</li></ol><p><img src="'+l+'" alt="Screenshot einer Adresse mit Hervorhebung der Meldung „Sie sind nicht berechtigt, diese Aktion durchzuführen.“" data-zoomable="true"></p>',33),e("p",null,[e("video",{src:o,controls:"",playsinline:"",preload:"metadata"},[i(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/error_permission.webm",download:""},"herunterladen"),i(" anstelle des Videos. ")])],-1),t('<p>Die Rechte sind nach Objektart und Stufe vergeben – ansehen, bearbeiten, löschen. Der häufigste Fall in der Praxis ist deshalb nicht ein gesperrter Bereich, sondern ein fehlendes Löschrecht: Mit der mitgelieferten Rolle „Editor“ dürfen Sie alle Fachdaten anlegen und ändern, aber nichts davon löschen. Welche Rollen es gibt und was sie umfassen, beschreibt Kapitel <a href="./../teil-b-betrieb-admin-qgis/19-rollen-und-rechte.html">Rollen und Rechte</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ein fehlendes Recht kann sich auch als vollständig fehlender Inhalt zeigen, ohne Button und ohne Meldung. So bleibt die Gruppe der externen Kartendienste in der Legende der Karte aus, wenn Ihr Konto sie nicht lesen darf, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a>. Vermissen Sie etwas, das hier beschrieben ist, fragen Sie Ihre Administration, bevor Sie es für einen Fehler halten.</p></div><h2 id="_18-4-karte-oder-diagramm-bleibt-leer" tabindex="-1">18.4 Karte oder Diagramm bleibt leer <a class="header-anchor" href="#_18-4-karte-oder-diagramm-bleibt-leer" aria-label="Permalink to &quot;18.4 Karte oder Diagramm bleibt leer&quot;">​</a></h2><p>Eine leere Karte ist selten ein Defekt. Gehen Sie die Ursachen der Reihe nach durch:</p><ol><li><strong>Das falsche Projekt.</strong> Die Projektauswahl in der Kopfzeile bestimmt, was jede Ansicht zeigt. Prüfen Sie sie zuerst, siehe Abschnitt <a href="./01-erste-schritte.html#_1-3-projekt-auswahlen-und-wechseln">Projekt auswählen und wechseln</a>.</li><li><strong>Der Kartenausschnitt liegt woanders.</strong> Die Karte rückt nicht von selbst auf die Daten, sondern öffnet sich dort, wo Sie sie zuletzt verlassen haben – nach einem Projektwechsel also womöglich hunderte Kilometer entfernt. Klappen Sie die Legende auf und wählen Sie beim Eintrag „Adresse“ „Auf Ausdehnung zoomen“, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a>.</li><li><strong>Der Layer ist ausgeblendet.</strong> Ein- und ausgeblendete Layer merkt sich der Browser über die Sitzung hinaus. Was Sie gestern ausgeblendet haben, fehlt heute noch.</li><li><strong>Die Zoomstufe reicht nicht.</strong> Beschriftungen und externe Kartendienste erscheinen erst ab einer bestimmten Zoomstufe. Zoomen Sie weiter hinein.</li><li><strong>Ein Recht fehlt.</strong> Siehe Abschnitt <a href="#_18-3-fehlende-rechte-erkennen">Fehlende Rechte erkennen</a>.</li></ol><p><img src="'+u+'" alt="Screenshot der Karte ohne Netzdaten im Ausschnitt, mit Hervorhebung der Projektauswahl in der Kopfzeile und des Eintrags „Adresse“ in der Legende" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Fehlt nur die Hintergrundkarte und die Netzdaten sind da, liegt es am Kartendienst und nicht an Ihren Daten. Qonnectra meldet das mit „Es konnten keine Kacheln geladen werden.“ Arbeiten lässt sich trotzdem: Alle Objekte sind weiter anklickbar.</p></div><p>Bei den Auswertungen kommen zwei weitere Ursachen dazu:</p><ul><li><strong>Das Dashboard zeigt alte Zahlen.</strong> Die Kennzahlen werden bis zu fünf Minuten zwischengespeichert; frisch erfasste Daten erscheinen verzögert, siehe Kapitel <a href="./04-dashboard.html">Dashboard</a>.</li><li><strong>Es fehlen Spleiße.</strong> Störungsanalyse, Netzschema und Faserweg rechnen über die Faserverbindungen. Sind für den betrachteten Bereich keine angelegt, ist das Ergebnis leer, obwohl Kabel vorhanden sind, siehe Kapitel <a href="./06-stoerungsanalyse.html">Störungsanalyse</a> und <a href="./15-faserweg.html">Faserweg</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Eine Tabelle, die „Keine Ergebnisse gefunden“ zeigt, obwohl Sie nichts gefiltert haben und Daten vorhanden sein müssten, kann auch eine gestörte Verbindung zum Server bedeuten: Qonnectra unterscheidet an dieser Stelle nicht zwischen „nichts gefunden“ und „nicht geladen“. Laden Sie die Seite einmal neu, bevor Sie weitersuchen.</p></div><h2 id="_18-5-was-das-support-team-von-ihnen-braucht" tabindex="-1">18.5 Was das Support-Team von Ihnen braucht <a class="header-anchor" href="#_18-5-was-das-support-team-von-ihnen-braucht" aria-label="Permalink to &quot;18.5 Was das Support-Team von Ihnen braucht&quot;">​</a></h2><p>Je genauer die Meldung, desto schneller die Antwort. Halten Sie fest:</p><ul><li><strong>Den Wortlaut der Meldung</strong>, am besten als Bildschirmfoto der ganzen Ansicht.</li><li><strong>Was Sie getan haben</strong>, Schritt für Schritt bis zu dem Punkt, an dem es schiefging, und was Sie stattdessen erwartet hatten.</li><li><strong>Das Projekt und das Objekt</strong>, an dem es passiert ist – mit Adress-ID, Trassen-ID oder Rohrname, nicht nur „eine Adresse in Musterstadt“.</li><li><strong>Die Adresse aus der Adresszeile des Browsers</strong>. Sie enthält die Ansicht und das Objekt und ist deshalb oft die hilfreichste Angabe überhaupt.</li><li><strong>Datum und ungefähre Uhrzeit.</strong> Die Anwendung schreibt Fehler von sich aus in das Protokoll des Servers; mit der Uhrzeit findet Ihre Administration den passenden Eintrag, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/28-betrieb-der-instanz.html">Betrieb der Instanz</a>.</li><li><strong>Die Versionsnummer</strong> aus der Kopfzeile, z. B. „v1.7.0“, sowie Browser und Betriebssystem.</li></ul><p><img src="'+c+'" alt="Screenshot der Kopfzeile mit Hervorhebung der Projektauswahl links und der Versionsnummer rechts" data-zoomable="true"></p><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Legen Sie Ihr Passwort niemals bei. Niemand aus dem Support und niemand aus Ihrer Administration braucht es – ein Konto lässt sich auch ohne zurücksetzen.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Ist die Anwendung gar nicht erreichbar oder antwortet sie auf jeder Seite mit einem Fehler, ist das kein Fall für die Fachabteilung, sondern für den Betrieb der Instanz. Nennen Sie dann zusätzlich, ob es nur Sie betrifft oder alle im Haus.</p></div>',16)])])}const v=r(g,[["render",m]]);export{A as __pageData,v as default};
